134→    const supabase = createClient(SUPABASE_URL, SUPABASE_SERVICE_ROLE_KEY);
135→
136→    // Fetch ranking config
137→    const { data: rankingConfig } = await supabase.from("ranking_config").select("*").limit(1).single();
138→    const cfg = {
139→      model: rankingConfig?.model || "gpt-4o-mini",
140→      temperature: rankingConfig?.temperature ?? 0.2,
141→      max_resume_chars: rankingConfig?.max_resume_chars ?? 4000,
142→      num_interview_questions: rankingConfig?.num_interview_questions ?? 5,
143→    };
144→    const resumeParsePrompt: string | null = rankingConfig?.resume_parse_prompt || null;
145→    const deepScoringPrompt: string | null = rankingConfig?.deep_scoring_prompt || null;
146→
147→    const { job_id, resume_ids } = await req.json();
148→    if (!job_id) throw new Error("Missing job_id");
149→
150→    // Rate limit: 3 jobs/min
