 22→  { key: "deep_scoring", label: "Deep Scoring" },
 23→] as const;
 24→
 25→type PromptType = typeof PROMPT_TYPES[number]["key"];
 26→
 27→const DEFAULT_PROMPTS: Record<PromptType, string> = {
 28→  jd_analysis: `You are an expert recruiter. Analyze a job description and extract structured intelligence including role_type, seniority, domain, critical_must_haves, preferred_must_haves, nice_to_have, tools, evaluation_dimensions with rubrics. Return ONLY valid JSON.`,
 29→  resume_parse: `You are an expert resume parser. Extract structured data: candidate_name, skills_with_evidence, roles_with_dates, projects, tools, education, certifications, domain_experience, leadership_signals. Return ONLY valid JSON.`,
 30→  deep_scoring: `You are an expert recruiter performing deep candidate evaluation. Score each evaluation dimension 0-100 using the provided rubric. Return hard_fit, category_scores, strengths, gaps, interview_questions, explanation, confidence. Return ONLY valid JSON.`,
 31→};
 32→
 33→const SAMPLE_INPUTS: Record<PromptType, string> = {
 34→  jd_analysis: `Senior Full-Stack Engineer - FinTech\nWe need a senior engineer with 5+ years experience in React, Node.js, and PostgreSQL. Must have experience with payment systems. Nice to have: AWS, Docker, GraphQL. Remote-friendly.`,
 35→  resume_parse: `John Doe\nSenior Software Engineer\n5 years at TechCorp building React/Node apps.\nSkills: React, TypeScript, Node.js, PostgreSQL, AWS\nBS Computer Science, MIT 2018`,
 36→  deep_scoring: `Evaluate this candidate against the job requirements:\nCandidate has 5 years React experience, strong Node.js, basic PostgreSQL.\nJob requires: 5+ years React, Node.js, PostgreSQL, payment systems experience.\nCandidate has no payment systems experience.`,
 37→};
 38→
 39→interface PromptVersion {
 40→  id: string;
 41→  prompt_type: string;
 42→  label: string;
 43→  prompt_text: string;
 44→  model: string;
 45→  temperature: number;
 46→  is_active: boolean;
 47→  test_result_json: any;
 48→  notes: string;
 49→  created_at: string;
 50→}
 51→
 52→interface RankingConfig {
 53→  id: string;
 54→  model: string;
 55→  temperature: number;
 56→  max_resume_chars: number;
 57→  num_interview_questions: number;
 58→  jd_analysis_prompt: string;
 59→  resume_parse_prompt: string;
 60→  deep_scoring_prompt: string;
 61→  updated_at: string;
 62→}
 63→
 64→const AIPromptsTab = () => {
 65→  const { user } = useAuth();
 66→  const qc = useQueryClient();
 67→  const [config, setConfig] = useState<RankingConfig | null>(null);
 68→  const [loading, setLoading] = useState(true);
 69→  const [saving, setSaving] = useState(false);
 70→  const [activeTab, setActiveTab] = useState<"config" | "studio">("config");
 71→  const [studioType, setStudioType] = useState<PromptType>("jd_analysis");
 72→  const [showHistory, setShowHistory] = useState(false);
 73→  const [compareIds, setCompareIds] = useState<[string, string] | null>(null);
 74→  const [testInput, setTestInput] = useState("");
 75→  const [testingId, setTestingId] = useState<string | null>(null);
 76→  const [newVersionDialog, setNewVersionDialog] = useState(false);
 77→  const [newForm, setNewForm] = useState({ label: "", prompt_text: "", model: "gpt-4o-mini", temperature: 0.2, notes: "" });
 78→
 79→  useEffect(() => { fetchConfig(); }, []);
 80→
 81→  const fetchConfig = async () => {
 82→    const { data, error } = await supabase
 83→      .from("ranking_config")
 84→      .select("id, model, temperature, max_resume_chars, num_interview_questions, jd_analysis_prompt, resume_parse_prompt, deep_scoring_prompt, updated_at")
 85→      .limit(1).single();
 86→    if (error) toast.error("Error loading config: " + error.message);
 87→    else setConfig(data as unknown as RankingConfig);
 88→    setLoading(false);
 89→  };
 90→
 91→  const { data: versions, isLoading: versionsLoading } = useQuery({
 92→    queryKey: ["prompt_versions", studioType],
 93→    queryFn: async () => {
 94→      const { data, error } = await supabase
 95→        .from("prompt_versions")
 96→        .select("*")
 97→        .eq("prompt_type", studioType)
 98→        .order("created_at", { ascending: false });
 99→      if (error) throw error;
100→      return data as PromptVersion[];
101→    },
102→  });
103→
104→  const handleSaveConfig = async () => {
105→    if (!config) return;
106→    setSaving(true);
107→    const { id, updated_at, ...updates } = config;
108→    const { error } = await supabase.from("ranking_config").update(updates as any).eq("id", id);
109→    setSaving(false);
110→    if (error) toast.error(error.message);
111→    else { toast.success("Configuration saved"); fetchConfig(); }
112→  };
113→
114→  const handleResetConfig = () => {
115→    if (!config) return;
116→    setConfig({
117→      ...config, model: "gpt-4o-mini", temperature: 0.2, max_resume_chars: 4000, num_interview_questions: 5,
118→      jd_analysis_prompt: DEFAULT_PROMPTS.jd_analysis,
119→      resume_parse_prompt: DEFAULT_PROMPTS.resume_parse,
120→      deep_scoring_prompt: DEFAULT_PROMPTS.deep_scoring,
121→    });
122→  };
123→
124→  const updateConfig = (field: keyof RankingConfig, value: any) => {
125→    if (config) setConfig({ ...config, [field]: value });
126→  };
127→
128→  const createVersion = async () => {
129→    if (!newForm.label || !newForm.prompt_text) { toast.error("Label and prompt text are required"); return; }
130→    const { error } = await supabase.from("prompt_versions").insert({
131→      prompt_type: studioType,
132→      label: newForm.label,
133→      prompt_text: newForm.prompt_text,
134→      model: newForm.model,
135→      temperature: newForm.temperature,
136→      notes: newForm.notes,
137→      created_by: user?.id,
138→    } as any);
139→    if (error) { toast.error(error.message); return; }
140→    toast.success("Version created");
141→    qc.invalidateQueries({ queryKey: ["prompt_versions", studioType] });
142→    setNewVersionDialog(false);
143→    setNewForm({ label: "", prompt_text: "", model: "gpt-4o-mini", temperature: 0.2, notes: "" });
144→  };
145→
146→  const activateVersion = async (v: PromptVersion) => {
147→    // Deactivate all, activate selected
148→    await supabase.from("prompt_versions").update({ is_active: false } as any).eq("prompt_type", studioType);
149→    await supabase.from("prompt_versions").update({ is_active: true } as any).eq("id", v.id);
150→
151→    // Also update ranking_config with this prompt
152→    const promptField = `${studioType}_prompt` as keyof RankingConfig;
153→    if (config) {
154→      await supabase.from("ranking_config").update({
155→        [promptField]: v.prompt_text,
156→        model: v.model,
157→        temperature: v.temperature,
158→      } as any).eq("id", config.id);
159→      fetchConfig();
160→    }
161→    toast.success(`"${v.label}" activated and deployed`);
162→    qc.invalidateQueries({ queryKey: ["prompt_versions", studioType] });
163→  };
164→
165→  const testVersion = async (v: PromptVersion) => {
166→    const input = testInput || SAMPLE_INPUTS[studioType];
167→    setTestingId(v.id);
168→    try {
169→      const { data, error } = await supabase.functions.invoke("test-prompt", {
170→        body: { prompt_text: v.prompt_text, model: v.model, temperature: v.temperature, sample_input: input },
171→      });
172→      if (error) throw error;
173→      // Save test result
174→      await supabase.from("prompt_versions").update({ test_result_json: data } as any).eq("id", v.id);
175→      qc.invalidateQueries({ queryKey: ["prompt_versions", studioType] });
176→      toast.success(`Test complete (${data.latency_ms}ms, ${data.tokens.total_tokens} tokens)`);
177→    } catch (err: any) {
178→      toast.error("Test failed: " + err.message);
179→    }
180→    setTestingId(null);
181→  };
182→
183→  const deleteVersion = async (v: PromptVersion) => {
184→    if (!confirm(`Delete version "${v.label}"?`)) return;
185→    await supabase.from("prompt_versions").delete().eq("id", v.id);
186→    qc.invalidateQueries({ queryKey: ["prompt_versions", studioType] });
187→    toast.success("Version deleted");
188→  };
189→
190→  const openNewFromCurrent = () => {
191→    const promptField = `${studioType}_prompt` as keyof RankingConfig;
192→    setNewForm({
193→      label: `v${(versions?.length ?? 0) + 1}`,
194→      prompt_text: (config?.[promptField] as string) || DEFAULT_PROMPTS[studioType],
195→      model: config?.model || "gpt-4o-mini",
196→      temperature: config?.temperature ?? 0.2,
197→      notes: "",
198→    });
199→    setNewVersionDialog(true);
200→  };
